        ctx.beginPath();ctx.arc(.178,.647,.016,0,Math.PI*2);ctx.moveTo(.194,.647);ctx.lineTo(.219,.647);ctx.lineTo(.219,.658);ctx.stroke();
        text('·',.178,.647,.021,'#b2eece');
